<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext};
use Sentinel\Repositories\PermissionRepository;
final class BusinessReminderService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly ContractRenewalService $renewals,private readonly PermissionRepository $permissions) {}
    public function list():array {return $this->db->fetchAll('SELECT * FROM business_reminders WHERE company_id=:company ORDER BY reminder_id DESC LIMIT 500',['company'=>$this->company()]);}
    public function tick():array {return $this->atomic(function(){$renewals=$this->renewals->applyDue();$now=gmdate('Y-m-d H:i:s');$this->db->execute("UPDATE open_shift_offers SET state='EXPIRED',revision=revision+1 WHERE company_id=:company AND state='OPEN' AND deadline_at<=:now",['company'=>$this->company(),'now'=>$now]);$findings=[];foreach($this->db->fetchAll("SELECT appointment_id FROM visitor_appointments WHERE company_id=:company AND state='CHECKED_IN' AND departure_due<:now LIMIT 1001",['company'=>$this->company(),'now'=>$now])as$r)$findings['visitor:'.$r['appointment_id']]='Visitor appointment #'.$r['appointment_id'].' has an overdue checkout. Contact the site and verify departure.';foreach($this->db->fetchAll("SELECT fleet_id,next_service_on,next_service_km FROM fleet_vehicles WHERE company_id=:company AND state<>'RETIRED' AND (odometer_km>=next_service_km OR next_service_on<=:date) LIMIT 1001",['company'=>$this->company(),'date'=>gmdate('Y-m-d')])as$r)$findings['fleet:'.$r['fleet_id'].':'.$r['next_service_on'].':'.$r['next_service_km']]='Fleet vehicle #'.$r['fleet_id'].' is due for service.';foreach($this->db->fetchAll("SELECT contract_id,end_date FROM contracts WHERE company_id=:company AND deleted_at IS NULL AND status IN ('ACTIVE','EXPIRED') AND end_date<=:date LIMIT 1001",['company'=>$this->company(),'date'=>gmdate('Y-m-d',time()+30*86400)])as$r)$findings['contract:'.$r['contract_id'].':'.$r['end_date']]='Contract #'.$r['contract_id'].' expires/expires soon: '.$r['end_date'].'. Review renewal terms.';$backup=$this->db->fetch('SELECT state,restore_state,started_at FROM encrypted_backups WHERE company_id=:company ORDER BY backup_id DESC LIMIT 1',['company'=>$this->company()]);if($backup&&($backup['state']==='FAILED'||$backup['restore_state']==='FAILED'||($backup['state']==='RUNNING'&&$backup['started_at']<gmdate('Y-m-d H:i:s',time()-7200))))$findings['backup:attention']='The latest encrypted backup failed, failed verification or appears stalled. Review recovery status.';$schedule=$this->db->fetch('SELECT * FROM backup_schedules WHERE company_id=:company AND enabled=1',['company'=>$this->company()]);if($schedule&&($schedule['last_success_at']===null||strtotime($schedule['last_success_at'].' UTC')<time()-(int)$schedule['interval_hours']*7200))$findings['backup:late']='Scheduled backups lack a recent successful receipt.';foreach($this->db->fetchAll("SELECT t.certificate_id,t.expires_on FROM learning_certificates t JOIN learning_assignments a ON a.company_id=t.company_id AND a.assignment_id=t.assignment_id JOIN employees e ON e.company_id=a.company_id AND e.employee_id=a.employee_id WHERE t.company_id=:company AND t.revoked_at IS NULL AND e.employment_status='ACTIVE' AND t.expires_on<=:date LIMIT 1001",['company'=>$this->company(),'date'=>gmdate('Y-m-d',time()+30*86400)])as$r)$findings['course-certificate:'.$r['certificate_id']]='Internal course certificate #'.$r['certificate_id'].' expires/expires soon: '.$r['expires_on'].'. Schedule refresher training.';
        foreach($this->db->fetchAll("SELECT assignment_id FROM learning_assignments WHERE company_id=:company AND state='ASSIGNED' AND due_on<:today LIMIT 1001",['company'=>$this->company(),'today'=>gmdate('Y-m-d')])as$r)$findings['course-overdue:'.$r['assignment_id']]='Learning assignment #'.$r['assignment_id'].' is overdue.';
        foreach($this->db->fetchAll('SELECT stock_id FROM stock_items WHERE company_id=:company AND available_quantity<=reorder_level LIMIT 1001',['company'=>$this->company()])as$r)$findings['stock-low:'.$r['stock_id']]='Stock item #'.$r['stock_id'].' is at or below its reorder level.';
        foreach($this->db->fetchAll("SELECT allocation_id FROM stock_allocations WHERE company_id=:company AND state IN ('PENDING_ACCEPTANCE','ISSUED','PARTIAL') AND due_at<:now LIMIT 1001",['company'=>$this->company(),'now'=>$now])as$r)$findings['stock-due:'.$r['allocation_id']]='Stock allocation #'.$r['allocation_id'].' requires overdue acceptance/return follow-up.';
        foreach($this->db->fetchAll("SELECT case_id FROM investigation_cases WHERE company_id=:company AND state<>'CLOSED' AND due_on<:date LIMIT 1001",['company'=>$this->company(),'date'=>gmdate('Y-m-d')])as$r)$findings['investigation-due:'.$r['case_id']]='Investigation #'.$r['case_id'].' is overdue.';
        if(count($findings)>1000)throw new \RuntimeException('Too many reminders; narrow operational records before continuing.');$setting=$this->db->fetch('SELECT reminder_user_id FROM business_operation_settings WHERE company_id=:company',['company'=>$this->company()]);$recipient=$setting?(string)$setting['reminder_user_id']:null;$allowed=$recipient&&$this->db->fetch("SELECT user_id FROM users WHERE company_id=:company AND user_id=:user AND status='ACTIVE'",['company'=>$this->company(),'user'=>$recipient])&&$this->permissions->userHasPermission($recipient,'pilot_setup.view')&&!$this->permissions->userHasPermission($recipient,'site_scope.restricted');$created=0;foreach($findings as$key=>$message){$old=$this->db->fetch('SELECT reminder_id,state FROM business_reminders WHERE company_id=:company AND source_key=:key',['company'=>$this->company(),'key'=>$key]);if($old&&$old['state']==='OPEN')continue;if($old)$this->db->execute("UPDATE business_reminders SET state='OPEN',created_at=:now,resolved_at=NULL,message=:message WHERE company_id=:company AND reminder_id=:id",['now'=>$now,'message'=>$message,'company'=>$this->company(),'id'=>$old['reminder_id']]);else $this->db->execute('INSERT INTO business_reminders(company_id,source_key,message,created_at) VALUES(:company,:key,:message,:now)',['company'=>$this->company(),'key'=>$key,'message'=>$message,'now'=>$now]);if($allowed)$this->db->execute('INSERT INTO notifications(company_id,recipient_user_id,event_type,title,message) VALUES(:company,:user,:type,:title,:message)',['company'=>$this->company(),'user'=>$recipient,'type'=>'BUSINESS_OPERATIONS_REMINDER','title'=>'Business operations follow-up','message'=>$message]);$created++;}foreach($this->db->fetchAll("SELECT reminder_id,source_key FROM business_reminders WHERE company_id=:company AND state='OPEN'",['company'=>$this->company()])as$r)if(!isset($findings[$r['source_key']]))$this->db->execute("UPDATE business_reminders SET state='RESOLVED',resolved_at=:now WHERE company_id=:company AND reminder_id=:id",['now'=>$now,'company'=>$this->company(),'id'=>$r['reminder_id']]);$this->audit->record('business_operations','worker_completed',null,[],[],['new_reminders'=>$created]);return ['reminders'=>$created,'renewals'=>$renewals];});}
}
